out = {"symptoms": {}, "diseases": {}, "risk_advice": {}}
for item in SYM.split("|"):
    k, v = item.split(":", 1)
    out["symptoms"][k] = v
for line in DIS.strip().splitlines():
    en, hi, pre, diet = [x.strip() for x in line.split("|")]
    out["diseases"][en] = {"name": hi, "precautions": [p.strip() for p in pre.split(";")], "diet": [d.strip() for d in diet.split(";")]}
for key, levels in RISK.items():
    out["risk_advice"][key] = {lv: {"precautions": [x.strip() for x in a.split(";")], "diet": [x.strip() for x in b.split(";")]} for lv, (a, b) in levels.items()}
json.dump(out, open("data/hindi.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)

# check against the English data
kb = json.load(open("data/knowledge.json"))["diseases"]
prof = json.load(open("models/symptom_profiles.json"))
print("diseases:", len(out["diseases"]), "missing:", [d for d in kb if d not in out["diseases"]])
print("symptoms missing Hindi:", [s for s in prof["symptoms"] if s not in out["symptoms"] and not s.endswith(".1")])
